mapper.select:
select * from ( SELECT CASE WHEN ISSUE.ISSUE_EDATE >= TO_DATE(#{listingDate},'YYYY-MM-DD') or ISSUE.TENDER_EDATE >= TO_DATE(#{listingDate},'YYYY-MM-DD') THEN '01' WHEN (ISSUE.ISSUE_EDATE < TO_DATE(#{listingDate},'YYYY-MM-DD') or ISSUE.TENDER_EDATE < TO_DATE(#{listingDate},'YYYY-MM-DD')) and PRODUCT.CIRCULATION_CODE is null THEN '02' WHEN (ISSUE.ISSUE_EDATE < TO_DATE(#{listingDate},'YYYY-MM-DD') or ISSUE.TENDER_EDATE < TO_DATE(#{listingDate},'YYYY-MM-DD')) and PRODUCT.CIRCULATION_CODE is not null THEN '03'
ELSE NULL END AS issueStage, PRODUCT_ADD.ISSUE_STATUS as issueStatus, PRODUCT.FINPROD_NAME as finprodName, PRODUCT.FINPROD_ID as finprodId FROM FIN_PRODUCT PRODUCT LEFT JOIN FIN_PRODUCT_ADD PRODUCT_ADD ON PRODUCT.FINPROD_ID = PRODUCT_ADD.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE ISSUE ON PRODUCT.FINPROD_ID = ISSUE.FINPROD_ID where PRODUCT.FINPROD_TYPE2=#{finprodType2,jdbcType=VARCHAR} AND PRODUCT.TRADE_MARKET in (#{TRADE_PLACE_01},#{TRADE_PLACE_02}) and PRODUCT_ADD.ISSUE_STATUS not in (#{ISSUE_STATUS_02}) and PRODUCT.CIRCULATION_CODE is null
and PRODUCT_ADD.LISTING_DATE=#{listingDate,jdbcType=DATE}
) t where t.issueStage=#{issueStage,jdbcType=VARCHAR}
